begin;
create table public.employee_loan_reviewers(tenant_id uuid not null references public.tenants(id) on delete cascade,user_id uuid not null,primary key(tenant_id,user_id),foreign key(tenant_id,user_id) references public.memberships(tenant_id,user_id) on delete cascade);
insert into public.employee_loan_reviewers(tenant_id,user_id) select m.tenant_id,m.user_id from public.memberships m join auth.users u on u.id=m.user_id where lower(u.email) in ('bridget@nxt-workforce.com','kristian@nxt-workforce.com','nyasha@nxt-workforce.com') on conflict do nothing;
create table public.employee_loans(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,employee_id uuid not null,requested_by uuid not null,amount numeric(14,2) not null check(amount>0 and amount<=1000000),currency text not null default 'USD' check(currency='USD'),reason text not null check(length(trim(reason)) between 5 and 1000),status text not null default 'requested' check(status in ('requested','approved','declined','deducted')),reviewed_by uuid,reviewed_at timestamptz,decision_note text check(decision_note is null or length(decision_note)<=1000),payroll_item_id uuid references public.business_items(id),deducted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(tenant_id,employee_id) references public.employees(tenant_id,id),foreign key(tenant_id,requested_by) references public.memberships(tenant_id,user_id),foreign key(tenant_id,reviewed_by) references public.memberships(tenant_id,user_id));
create index employee_loans_employee_idx on public.employee_loans(tenant_id,employee_id,status,created_at);
alter table public.employee_loans enable row level security;alter table public.employee_loan_reviewers enable row level security;
create policy loan_reviewer_self on public.employee_loan_reviewers for select to authenticated using(user_id=auth.uid());
create policy loan_read on public.employee_loans for select to authenticated using(exists(select 1 from public.employees e where e.tenant_id=employee_loans.tenant_id and e.id=employee_loans.employee_id and e.user_id=auth.uid()) or exists(select 1 from public.employee_loan_reviewers r where r.tenant_id=employee_loans.tenant_id and r.user_id=auth.uid()));
grant select on public.employee_loans,public.employee_loan_reviewers to authenticated;

create function public.loan_snapshot(t uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare me public.employees;reviewer boolean;rows jsonb;begin if auth.uid() is null or not public.is_staff(t) then raise exception 'Staff access required';end if;select * into me from public.employees where tenant_id=t and user_id=auth.uid() and status='active' limit 1;reviewer:=exists(select 1 from public.employee_loan_reviewers where tenant_id=t and user_id=auth.uid());select coalesce(jsonb_agg(to_jsonb(l)||jsonb_build_object('employee_name',e.name,'is_mine',e.user_id=auth.uid()) order by l.created_at desc),'[]'::jsonb) into rows from public.employee_loans l join public.employees e on e.tenant_id=l.tenant_id and e.id=l.employee_id where l.tenant_id=t and (reviewer or e.user_id=auth.uid());return jsonb_build_object('reviewer',reviewer,'employee',case when me.id is null then null else jsonb_build_object('id',me.id,'name',me.name) end,'loans',rows);end;$$;
revoke all on function public.loan_snapshot(uuid) from public,anon;grant execute on function public.loan_snapshot(uuid) to authenticated;

create function public.request_employee_loan(t uuid,amount numeric,reason text) returns public.employee_loans language plpgsql security definer set search_path='' as $$declare e public.employees;l public.employee_loans;recipient record;begin if auth.uid() is null or not public.is_staff(t) then raise exception 'Staff access required';end if;select * into e from public.employees where tenant_id=t and user_id=auth.uid() and status='active' limit 1;if not found then raise exception 'Your login is not linked to an active employee';end if;if amount is null or amount<=0 or amount>1000000 or round(amount,2)<>amount then raise exception 'Enter a valid loan amount with at most two decimals';end if;if length(trim(coalesce(reason,''))) not between 5 and 1000 then raise exception 'Add a reason for the loan';end if;insert into public.employee_loans(tenant_id,employee_id,requested_by,amount,reason) values(t,e.id,auth.uid(),round(amount,2),trim(reason)) returning * into l;for recipient in select u.email from public.employee_loan_reviewers r join auth.users u on u.id=r.user_id where r.tenant_id=t and r.user_id<>auth.uid() and u.email is not null loop insert into public.notification_outbox(tenant_id,recipient,subject,body) values(t,recipient.email,'Employee loan request: '||e.name,e.name||' requested a USD '||to_char(l.amount,'FM999999999990.00')||' employee loan. Reason: '||l.reason||'. Open Employee Loans in NXT Business OS to review.');end loop;return l;end;$$;
revoke all on function public.request_employee_loan(uuid,numeric,text) from public,anon;grant execute on function public.request_employee_loan(uuid,numeric,text) to authenticated;

create function public.decide_employee_loan(t uuid,loan_id uuid,decision text,note text default '') returns public.employee_loans language plpgsql security definer set search_path='' as $$declare l public.employee_loans;e public.employees;recipient text;new_status text;begin if auth.uid() is null or not exists(select 1 from public.employee_loan_reviewers where tenant_id=t and user_id=auth.uid()) then raise exception 'Loan reviewer access required';end if;select * into l from public.employee_loans where tenant_id=t and id=loan_id for update;if not found then raise exception 'Loan request unavailable';end if;if l.status<>'requested' then raise exception 'This loan has already been reviewed';end if;if l.requested_by=auth.uid() then raise exception 'You cannot approve or decline your own loan request';end if;if decision not in ('approve','decline') then raise exception 'Choose approve or decline';end if;new_status:=case when decision='approve' then 'approved' else 'declined' end;update public.employee_loans set status=new_status,reviewed_by=auth.uid(),reviewed_at=now(),decision_note=nullif(trim(coalesce(note,'')),''),updated_at=now() where id=loan_id returning * into l;select * into e from public.employees where tenant_id=t and id=l.employee_id;select u.email into recipient from auth.users u where u.id=e.user_id;if recipient is not null then insert into public.notification_outbox(tenant_id,recipient,subject,body) values(t,recipient,'Employee loan '||new_status,(case when new_status='approved' then 'Your employee loan request for USD '||to_char(l.amount,'FM999999999990.00')||' was approved and will be deducted from your next payroll.' else 'Your employee loan request for USD '||to_char(l.amount,'FM999999999990.00')||' was declined.' end)||case when l.decision_note is not null then ' Note: '||l.decision_note else '' end);end if;return l;end;$$;
revoke all on function public.decide_employee_loan(uuid,uuid,text,text) from public,anon;grant execute on function public.decide_employee_loan(uuid,uuid,text,text) to authenticated;

alter function public.payroll_v3(uuid,jsonb,boolean) rename to payroll_v3_before_loans_v1;alter function public.payroll_v3_before_loans_v1(uuid,jsonb,boolean) set schema nxt_private;revoke all on function nxt_private.payroll_v3_before_loans_v1(uuid,jsonb,boolean) from public,anon,authenticated;
create function public.payroll_v3(t uuid,v jsonb,save_draft boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare loan_total numeric:=0;loan_ids jsonb:='[]'::jsonb;manual_other numeric:=coalesce((v->>'other_deductions')::numeric,0);adjusted jsonb;result jsonb;payroll_id uuid;row public.business_items;begin select coalesce(sum(l.amount),0),coalesce(jsonb_agg(l.id order by l.created_at),'[]'::jsonb) into loan_total,loan_ids from public.employee_loans l where l.tenant_id=t and l.employee_id=(v->>'employee_id')::uuid and l.status='approved' and l.payroll_item_id is null;adjusted:=jsonb_set(v,'{other_deductions}',to_jsonb(round(manual_other+loan_total,2)),true);result:=nxt_private.payroll_v3_before_loans_v1(t,adjusted,save_draft);if not save_draft then return result||jsonb_build_object('manual_other_deductions',manual_other,'loan_deduction',loan_total,'loan_ids',loan_ids);end if;payroll_id:=(result->>'id')::uuid;update public.business_items set payload=payload||jsonb_build_object('manual_other_deductions',manual_other,'loan_deduction',loan_total,'loan_ids',loan_ids) where id=payroll_id returning * into row;return to_jsonb(row);end;$$;
revoke all on function public.payroll_v3(uuid,jsonb,boolean) from public,anon;grant execute on function public.payroll_v3(uuid,jsonb,boolean) to authenticated;

alter function public.business_action(uuid,uuid,text,jsonb) rename to business_action_before_loans_v1;alter function public.business_action_before_loans_v1(uuid,uuid,text,jsonb) set schema nxt_private;revoke all on function nxt_private.business_action_before_loans_v1(uuid,uuid,text,jsonb) from public,anon,authenticated;
create function public.business_action(t uuid,r uuid,a text,v jsonb default '{}') returns public.business_items language plpgsql security definer set search_path='' as $$declare b public.business_items;result public.business_items;ids uuid[];expected_count int;actual_count int;expected_total numeric;actual_total numeric;begin select * into b from public.business_items where tenant_id=t and id=r for update;if not found then raise exception 'Record unavailable';end if;if a='finalise' and b.kind='payroll' and jsonb_array_length(coalesce(b.payload->'loan_ids','[]'::jsonb))>0 then select array_agg(value::uuid) into ids from jsonb_array_elements_text(b.payload->'loan_ids');expected_count:=coalesce(array_length(ids,1),0);expected_total:=coalesce((b.payload->>'loan_deduction')::numeric,0);select count(*),coalesce(sum(amount),0) into actual_count,actual_total from public.employee_loans where tenant_id=t and id=any(ids) and status='approved' and payroll_item_id is null;if actual_count<>expected_count or actual_total<>expected_total then raise exception 'Loan status changed. Recalculate this payroll draft before finalising';end if;end if;result:=nxt_private.business_action_before_loans_v1(t,r,a,v);if a='finalise' and result.kind='payroll' and jsonb_array_length(coalesce(result.payload->'loan_ids','[]'::jsonb))>0 then select array_agg(value::uuid) into ids from jsonb_array_elements_text(result.payload->'loan_ids');update public.employee_loans set status='deducted',payroll_item_id=result.id,deducted_at=now(),updated_at=now() where tenant_id=t and id=any(ids) and status='approved' and payroll_item_id is null;end if;return result;end;$$;
revoke all on function public.business_action(uuid,uuid,text,jsonb) from public,anon;grant execute on function public.business_action(uuid,uuid,text,jsonb) to authenticated;
commit;